    $display("[COV] Arbiter3_L2TLBImp_Anon.win2 = %0d", a_cov_win2);
    if (a_cov_win2 < 200) begin cov_fail++; $display("[COV] Arbiter3_L2TLBImp_Anon.win2 < 200"); end
    $display("[COV] Arbiter3_L2TLBImp_Anon.blocked = %0d", a_cov_blocked);
    if (a_cov_blocked < 200) begin cov_fail++; $display("[COV] Arbiter3_L2TLBImp_Anon.blocked < 200"); end
    $display("checks=%0d errors=%0d cov_fail=%0d", checks, errors, cov_fail);
    if (errors == 0 && cov_fail == 0 && checks > 0) $display("TEST PASSED");
    else $display("TEST FAILED");
    $finish;
  end
endmodule
